trans = {
    # 0 - 11: Austrian Elections & Archduke Battlefield
    "AUS_political_events.90.t": "Hasil Pemilihan Umum Kita",
    "AUS_political_events.90.desc": "Pemilihan umum pertama sejak peristiwa 'Peniadaan Parlemen Mandiri' telah selesai digelar. Partisipasi pemilih sangat tinggi seiring bangsa kita menyadari kehancuran apa yang menimpa negara jika mereka melalaikan kewajiban sebagai warga negara. Tiga kandidat utama bersaing sengit dengan selisih suara yang sangat tipis dalam penghitungan akhir.",
    "AUS_political_events.90.a": "Kurt Schuschnigg adalah seorang demokrat sejati di lubuk hatinya!",
    "AUS_political_events.90.a_tt": "§YKurt Schuschnigg§! menjadi pemimpin untuk partai §YDemokrat§!.",
    "AUS_political_events.90.b": "Karl Renner telah mengabdi dengan gemilang kepada kita sebelumnya!",
    "AUS_political_events.90.c": "Vinzenz Schumy dapat merangkul sebagian besar aspirasi pemilih!",
    "AUS_political_events.91.t": "[ROOT.GetLeader] Ingin Berada di Medan Laga",
    "AUS_political_events.91.desc": "Belakangan ini kita mendapati Adipati Agung kita, Yang Mulia [ROOT.GetLeader], tiada henti memikirkan situasi di garis depan. Beliau merasa tidak berbuat cukup dan berhasrat memimpin pasukannya secara langsung. Hari ini persoalan itu diangkat kembali; sang Adipati Agung berkehendak gagah berani memimpin prajuritnya dalam pertempuran dan menyerahkan roda pemerintahan kepada sosok lain.",
    "AUS_political_events.91.a": "Majulah ke medan laga, Adipati Agung! Kami akan menunjuk seseorang menjaga singgasana Anda",
    "AUS_political_events.91.b": "Bahkan seorang Adipati Agung pun harus tetap berada di istana",
    "AUS_political_events.91.a_tt": "Ibu Kota baru akan bernama §YVaduz§!",
    "AUS_political_events.91.a_tt2": "§YOtto von Habsburg§! menjadi Marsekal Lapangan §YTingkat 2§!",

    # 12 - 27: Alaska purchase & Liechtenstein lore
    "AUS_political_events.92.t": "[FROM.GetNameDefCap] Mengajukan Pembelian Alaska",
    "AUS_political_events.92.desc": "[FROM.GetLeader] dari [FROM.GetNameDef] telah menghubungi kita dengan permohonan untuk membeli wilayah [463.GetName]. Pada tahun 1867 ketika wilayah itu dibeli dari Kekaisaran Rusia oleh [USA.GetNameDef], tawaran penjualan semula pertama kali diajukan kepada [FROM.GetNameDef]. Tawaran itu ditolak kala itu, namun sejak saat itu mereka berubah pikiran dan kini ingin membeli wilayah tersebut dari kita. Sebagai imbalannya, mereka menawarkan bayaran yang sangat menggiurkan.",
    "AUS_political_events.92.a": "Kedaulatan wilayah kita tidak untuk dijual!",
    "AUS_political_events.92.b": "Kita tidak memerlukan [463.GetName]",
    "generic_this_might_cause_tt": "§RHal ini dapat memicu§!:",
    "AUS_political_events.93.t": "[FROM.GetNameDefCap] Menjual [463.GetName] kepada Kita",
    "AUS_political_events.93.desc": "Kita telah menerima kabar dari [FROM.GetLeader] bahwa mereka sepakat menjual wilayah [463.GetName] kepada kita dengan harga yang telah kita tawarkan. Wilayah tersebut akan dialihkan kepada kita segera agar proses integrasi dapat segera dimulai.",
    "AUS_political_events.93.a": "Luar biasa",
    "AUS_political_events.94.t": "[FROM.GetNameDefCap] Menolak Menjual [463.GetName]",
    "AUS_political_events.94.desc": "Meskipun kita menawarkan sejumlah besar uang kepada [FROM.GetNameDef] untuk memperoleh [463.GetName], mereka menolak kesepakatan ini. Kita memiliki klaim historis yang sangat sah atas [463.GetName] yang kini mereka tolak secara sepihak. Kita harus memikirkan jalan terbaik selanjutnya.",
    "AUS_political_events.94.a": "Patut dicoba walau gagal",
    "AUS_political_events.94.b": "Kita akan membebaskan mereka dengan kekuatan senjata!",
    "AUS_political_events.95.t": "Tentara [ROOT.GetAdjective] Kembali Pasca Ekspedisi yang Sukses",
    "AUS_political_events.95.desc": "Ketika Perang Austria-Prusia berakhir pada 22 Juli 1866, tentara gagah berani kita berbaris kembali ke tanah air. Konon dikisahkan ada satu prajurit lebih banyak di barisan saat pulang dibanding saat berangkat perang. Apakah kisah ini nyata atau sekadar legenda rakyat masih diperdebatkan. Namun kini kita dapat memastikan keajaiban itu terulang kembali saat tentara agung kita pulang, satu prajurit lebih kuat.",
    "AUS_political_events.95.a": "Selamat datang di [ROOT.GetNameDef]!",
    "AUS_political_events.95.a_tt": "Satu patriot sejati [ROOT.GetAdjective] telah bergabung ke dalam barisan kita",

    # 28 - 38: Faction invitations
    "AUS_political_events.96.t": "[FROM.GetNameDefCap] Ingin Bergabung dengan [ROOT.GetFactionName]",
    "AUS_political_events.96.desc": "[FROM.GetLeader] dari negara [FROM.GetName] yang baru saja beralih ke demokrasi telah mendekati kita memohon untuk bergabung ke dalam [ROOT.GetFactionName]. Kendati mereka berdiri sendirian sejak berakhirnya Perang Besar, iklim politik terkini dan memuncaknya ketegangan dunia membuat mereka berubah pikiran. Melihat mereka kini telah menjadi negara demokrasi sejati, mereka memilih merapat kepada kita, meyakinkan bahwa mereka akan menjadi aset tak ternilai bagi faksi kita!",
    "AUS_political_events.96.a": "Mereka sangat disambut baik untuk bergabung!",
    "AUS_political_events.96.b": "Kita tidak mempercayai mereka.",
    "AUS_political_events.97.t": "[FROM.GetNameDefCap] Menyambut Kita ke Dalam [ROOT.GetFactionName]",
    "AUS_political_events.97.desc": "Permohonan kita untuk bergabung dengan [ROOT.GetFactionName] telah disetujui! Kendati kita sangat yakin bahwa perubahan haluan drastis ini adalah apa yang dibutuhkan negeri kita, ada bobot tanggung jawab berat dalam situasi ini. Pasca Perang Besar kita memutuskan segala ikatan persekutuan dengan harapan bencana serupa tak akan terulang. Kini saat kita bernaung dalam rasa aman dari aliansi baru kita, hal itu disertai kesadaran mendalam bahwa perdamaian sejatinya adalah hal yang sangat rapuh.",
    "AUS_political_events.97.a": "Langkah ini mutlak harus diambil",
    "AUS_political_events.98.t": "[FROM.GetNameDefCap] Menolak Permohonan Kita Bergabung dengan [FROM.GetFactionName]",
    "AUS_political_events.98.desc": "Terlepas dari ikhtiar terbaik kita, permohonan yang kita kirimkan kepada pihak [FROM.GetAdjective] untuk bergabung ke dalam [FROM.GetFactionName] telah ditolak mentah-mentah. Jawaban mereka tidak menyertakan alasan yang jelas dan tampaknya kita kembali dibiarkan berjuang sendirian.",
    "AUS_political_events.98.a": "Sungguh keterlaluan perlakuan mereka!",
    "AUS_political_events.98.b": "Tampaknya kita harus menuntaskan segala sesuatunya sendiri!",

    # 39 - 54: Seyss-Inquart pressure & rejection
    "AUS_political_events.99.t": "[FROM.GetNameDefCap] Menolak Tuntutan Kita",
    "AUS_political_events.99.desc": "[GetRejectionAmounts]",
    "AUS_has_not_rejected_before": "[FROM.GetLeader] dari kepemimpinan [FROM.GetAdjective] telah membalas tuntutan kita. Surat diplomatik itu bernada sopan namun sarat akan nada penghinaan terselubung. Kekhawatiran kita dianggap angin lalu, membuktikan bahwa kecurigaan kita terhadap [FROM.GetNameDef] selama ini terbukti beralasan. Sebagian petinggi kita mendesak agar terus menekan pihak [FROM.GetAdjective] untuk tunduk demi memuluskan rencana masa depan kita terhadap mereka, sementara faksi minoritas berpendapat kita sebaiknya membiarkan pihak [FROM.GetAdjective] menikmati kemenangan semu ini.",
    "AUS_GER_cannot_take_a_no": "Terlepas dari tekanan hebat dan berkelanjutan terhadap [FROM.GetNameDef], [FROM.GetLeader] tetap teguh pada pendiriannya. Arthur Seyss-Inquart tidak akan diterima sebagai penasihat di dalam kabinet pemerintahan, terlepas dari apa pun gertakan kita. Kita terpaksa harus memutar otak mencari jalan lain, walau ini sekadar hambatan kecil.",
    "AUS_political_events.99.a": "Mereka akan tunduk kepada kita!",
    "AUS_refuses_to_submit": "Menolak Tunduk kepada Kita",
    "AUS_political_events.99.b": "Biarkan mereka menikmati ini sejenak, agar mereka lengah...",
    "AUS_bullied_austria": "Menindas [AUS.GetNameDef]",
    "AUS_political_events.100.t": "Tekanan Lanjutan untuk Mengangkat Arthur Seyss-Inquart",
    "AUS_political_events.100.desc": "\\nTerlepas dari penolakan tegas kita sebelumnya untuk mengangkat Arthur Seyss-Inquart ke dalam kabinet, pemimpin [FROM.GetAdjective] [FROM.GetLeader] tak henti-hentinya menuntut hal itu dilaksanakan. Kendati tekanan diplomatik kian menghimpit kita, kita tetap mempertahankan kedaulatan atas urusan dalam negeri kita, dan keputusan akhir tetap berada di tangan kita.",
    "AUS_political_events.100.a": "Pasti ada muslihat jahat di balik tekanan ini, jangan pernah gentar!",
    "AUS_trying_to_control_us": "Berupaya Mengendalikan Kita",
    "AUS_political_events.100.b": "Kita menanggung risiko pembalasan mematikan jika menolak",
    "AUS_political_events.101.t": "[FROM.GetNameDefCap] Menghentikan Upaya Memasang Arthur Seyss-Inquart",
    "AUS_political_events.101.desc": "Setelah sekian lama tarik-ulur atas persoalan yang sama sekali bukan urusan mereka, [FROM.GetNameDef] akhirnya menghentikan upaya ikut campur secara tidak sah dalam perpolitikan kita. Kita yakin mereka saat ini sangat mendendam kepada kita, namun itu bukan perhatian utama kita. Fokus utama kita sejak awal hingga selamanya adalah kejayaan [ROOT.GetNameDef].",
    "AUS_political_events.101.a": "Akhirnya reda juga",

    # 55 - 69: German Expansion plans & Mysterious Austrian Painter
    "AUS_political_events.102.t": "Rencana Ekspansi Sang Führer",
    "AUS_political_events.102.desc": "Dalam sebuah konferensi rahasia yang dihimpun oleh [ROOT.GetLeader], sang Führer membeberkan ambisinya mengenai arah ekspansi [ROOT.GetNameDef] di masa depan. Ekspansi pertama dipandang berisiko sangat minim. Rakyat [AUS.GetAdjective] tak berbeda dengan bangsa kita dan sebagian besar memiliki pandangan serupa, sebagaimana tercermin dalam iklim politik negeri tersebut. Sang Führer meyakini ekspansi ini dapat dicapai secara diplomatis, asalkan diberikan waktu yang cukup bagi berkembangnya sentimen pro-[ROOT.GetAdjective] di dalam [AUS.GetNameDef].",
    "AUS_political_events.102.a": "Gagasan yang sangat cemerlang!",
    "AUS_anschluss_ratio_ticking_down": "§YKekuatan Tempur Total Angkatan Darat§! yang dibutuhkan untuk memulai Fokus Nasional §YAnschluss§! akan diturunkan setiap pekan. Jumlah penurunannya sebanding dengan popularitas §YNetralitas§! di §Y[AUS.GetNameWithFlag]§!.",
    "AUS_anschluss_ratio_ticking_down_monarchist": "§YKekuatan Tempur Total Angkatan Darat§! yang dibutuhkan untuk memulai Fokus Nasional §YAnschluss§! akan diturunkan setiap pekan. Jumlah penurunannya sebanding dengan popularitas §YFasisme§! di §Y[AUS.GetNameWithFlag]§!.",
    "AUS_political_events.103.t": "Laporan Mengkhawatirkan atas Ekspansionisme [GER.GetAdjective]",
    "AUS_political_events.103.desc": "Kendati kita telah lama mencurigai niat [GER.GetAdjective] untuk menganeksasi kita, laporan intelijen yang mendarat di meja kita pagi ini menempatkan situasi dalam bahaya yang jauh lebih mengerikan. Terungkap bahwa sebuah konferensi baru saja digelar di mana [GER.GetLeader] menyuarakan rencana keji untuk mencaplok bangsa kita ke dalam wilayah mereka. Terlepas dari upaya kita merahasiakannya, informasi bocor ke publik dan parahnya disambut baik oleh partai-partai politik tertentu yang menganggapnya gagasan brilian. Kelompok-kelompok ini berpotensi merongrong tekad juang rakyat kita.",
    "AUS_political_events.103.a": "Ini kabar yang sangat buruk.",
    "AUS_political_events.104.t": "Sang Pelarian [GER.GetAdjective]",
    "AUS_political_events.104.desc": "Pagi ini sebuah pertemuan yang sangat tidak biasa terjadi. Kepemimpinan kita berhadapan langsung dengan pria misterius yang wajahnya terasa sangat akrab, bahkan suaranya pun tak asing. Pria ini mengaku sebagai seorang seniman berbakat yang telah mengembara dari [GER.GetNameDef] dan ingin membantu kita. Ia menegaskan bahwa dirinya adalah pemimpin ulung dan negeri kita sangat membutuhkan sosok seperti dirinya.\\n\\nKetika ditanyakan kepada para penjaga perbatasan, mereka membantah ada pria dengan nama itu melintasi perbatasan, dan nama Elizabeth Hiedler adalah nama yang paling mendekati.",
    "AUS_political_events.104.a": "Tidak akan pernah, kita tidak akan tertipu muslihat murahan itu",
    "AUS_political_events.104.b": "Apa yang mungkin salah?",
    "AUS_political_events.104.c": "Elizabeth..?",
    "AUS_british_monarch": "Pemimpin keturunan garis panjang Ratu-Ratu Inggris",
    "AUS_political_events.105.t": "[FROM.GetNameDefCap] Menarik Dukungan Mereka",
    "AUS_political_events.105.desc": "Menyusul perubahan konstelasi politik terkini, [FROM.GetNameDefCap] telah secara sepihak mencabut dukungan mereka terhadap kita. Kita kini berdiri sendirian menghadapi ancaman agresi di perbatasan.",
    "AUS_political_events.105.a": "Sikap pengecut yang khas.",
    "AUS_political_events.105.b": "Kita akan berdiri tegak sendirian!",
    "AUS_political_events.107.a_tt": "Saat memulai perang melawan [GER.GetNameDef], kita akan memperoleh:\\n",
    "AUS_political_events.125.t": "[FROM.GetNameDefCap] Menolak Undangan Kita",
    "AUS_political_events.125.desc": "Semula kita berharap pihak [FROM.GetAdjective] dapat melihat manfaat nyata dari bergabung kembali bersama kita, namun tampaknya kepahitan masa lalu telah membutakan pandangan mereka. Pemimpin kita [ROOT.GetLeader] menyikapi hal ini dengan ketabahan dan tekad baja: ini hanyalah rintangan kecil.",
    "AUS_political_events.125.a": "Jika mereka tidak bersama kita...",
    "AUS_news_events.1.t": "[AUS.GetNameDefCap] Menolak Anschluss [GER.GetAdjective]",
    "AUS_news_events.1.desc": "Menghadapi musuh yang jauh lebih perkasa, kepemimpinan [AUS.GetAdjective] memutuskan untuk tidak tunduk pada tuntutan terbaru [GER.GetAdjective] agar menyerah dan bergabung dengan [GER.GetNameDef]. Pasukan dari [GER.GetNameDef] telah berbaris di sepanjang perbatasan [AUS.GetAdjective], namun masih harus ditunggu apakah invasi skala penuh akan segera dilancarkan.\\n\\nPeristiwa ini terjadi setelah bertahun-tahun memburuknya hubungan kedua negara dan kian meningkatnya tekanan dari pihak [GER.GetAdjective] agar [AUS.GetNameDef] melebur ke dalam [GER.GetNameDef].",
    "AUS_news_events.1.a": "Kami mendoakan yang terbaik bagi [AUS.GetNameDef]...",
    "AUS_news_events.1.b": "Akan kita beri mereka pelajaran...",
    "AUS_news_events.1.c": "Östfrei!",
    "AUS_news_events.3.t": "Tragedi Gugurnya sang Penerbang Ulung",
    "AUS_news_events.3.desc": "Penerbang ulung (ace) tempur [AUS.GetAdjective] Godwin von Brumowski telah tewas dalam kecelakaan fatal bersama seorang siswa penerbang [HOL.GetAdjective] yang tengah ia latih di atas Lapangan Udara Schiphol.\\n\\nVon Brumowski adalah penerbang paling berprestasi dari jajaran Luftfahrtruppen yang perkasa. Dengan rekor 35 kemenangan udara tunggal, 12 kemenangan bersama, dan 8 kemenangan tak terkonfirmasi, ia mengabdi baik dalam Perang Besar maupun Perang Saudara 1934 di [AUS.GetNameDef].",
    "AUS_news_events.3.a": "Ia telah mengabdi dengan gagah berani, beristirahatlah dalam damai",
    "AUS_news_events.3.b": "Tragedi yang memilukan",
    "AUS_news_events.4.t": "Penerbang Ulung Nyaris Mengalami Petaka",
    "AUS_news_events.4.desc": "Penerbang ulung tempur [AUS.GetAdjective] Godwin von Brumowski nyaris meregang nyawa kemarin saat melatih seorang siswa penerbang [HOL.GetAdjective] di atas Lapangan Udara Schiphol.\\n\\nVon Brumowski adalah penerbang tempur paling berprestasi dari Luftfahrtruppen yang perkasa. Dengan torehan 35 kemenangan udara, 12 kemenangan bersama, dan 8 kemenangan tak terkonfirmasi, ia bertempur dalam Perang Besar serta Perang Saudara 1934 di [AUS.GetNameDef].\\n\\nKeduanya berhasil selamat tanpa luka parah dari musibah tersebut.",
    "AUS_news_events.4.a": "Sungguh lolos dari maut",

    # 70 - 100: Austrian diplomatic maneuvers
    "AUS_political_events.106.t": "Perjanjian Pertahanan Bersama",
    "AUS_political_events.106.desc": "Demi memperkokoh garis pertahanan kita di Eropa Tengah, para diplomat mengajukan pakta bantuan militer timbal balik dengan tetangga-tetangga kita.",
    "AUS_political_events.106.a": "Sepakati pakta pertahanan!",
    "AUS_political_events.106.b": "Netralitas mutlak tetap pilihan terbaik.",
    "AUS_political_events.107.t": "Pemberontakan Fasis di Wina",
    "AUS_political_events.107.desc": "Kelompok paramiliter fasis lokal yang disokong kekuatan asing melancarkan kerusuhan bersenjata di jalan-jalan kota Wina, menuntut integrasi segera dengan Reich.",
    "AUS_political_events.107.a": "Tumpas para pemberontak dengan kekuatan penuh!",
    "AUS_political_events.107.b": "Coba redam dengan perundingan.",
    "AUS_political_events.108.t": "Wina Berhasil Diamankan",
    "AUS_political_events.108.desc": "Pasukan keamanan pemerintah berhasil memulihkan ketertiban di ibu kota setelah memukul mundur anasir-anasir pemberontak bersenjata.",
    "AUS_political_events.108.a": "Ketertiban telah ditegakkan.",
    "AUS_political_events.109.t": "Krisis Perbatasan di Tyrol",
    "AUS_political_events.109.desc": "Insiden baku tembak terjadi di pos perbatasan pegunungan Tyrol, menguji kesiapan garnisun kita dalam mengantisipasi invasi.",
    "AUS_political_events.109.a": "Siagakan seluruh pos pertahanan perbatasan!",
    "AUS_political_events.109.b": "Hindari provokasi lebih lanjut.",
    "AUS_political_events.110.t": "Protes Internasional atas Agresi",
    "AUS_political_events.110.desc": "Liga Bangsa-Bangsa melayangkan nota keberatan resmi atas manuver militer agresif yang mengancam kedaulatan teritorial Austria.",
    "AUS_political_events.110.a": "Dukungan moral yang berharga.",
    "AUS_political_events.111.t": "Mobilisasi Bundesheer",
    "AUS_political_events.111.desc": "Mengingat bahaya invasi yang kian nyata, Komando Tinggi memerintahkan pemanggilan pasukan cadangan dan mobilisasi parsial Bundesheer.",
    "AUS_political_events.111.a": "Untuk tanah air dan kedaulatan!",
    "AUS_political_events.111.b": "Belum saatnya melakukan mobilisasi penuh.",
    "AUS_political_events.112.t": "Rakyat Menuntut Perlawanan",
    "AUS_political_events.112.desc": "Ribuan warga turun ke jalan menyuarakan kesetiaan kepada kemerdekaan Austria dan menolak tunduk pada aneksasi asing.",
    "AUS_political_events.112.a": "Rakyat berdiri teguh di belakang kita!",
    "AUS_political_events.113.t": "Bantuan Rahasia Tiba",
    "AUS_political_events.113.desc": "Konvoi pasokan amunisi dan persenjataan rahasia dari mitra internasional berhasil melintasi perbatasan untuk memperkuat logistik kita.",
    "AUS_political_events.113.a": "Bantuan yang tepat pada waktunya.",

    # 101 - 120: Joint military exercises & Empire reorganization
    "AUS_political_events.114.t": "[FROM.GetNameDef] Menawarkan Dukungan Industri",
    "AUS_political_events.114.desc": "Mengingat kesepakatan damai terkini antara negara kita, pihak [FROM.GetAdjective] menawarkan dukungan industri kepada kita. Kendati sektor industri kita lazimnya telah memenuhi standar, bantuan mereka tentu saja sangat disambut. Beberapa peringatan kehati-hatian disuarakan, menduga bahwa [FROM.GetNameDefCap] tentu memiliki motif terselubung dalam hal ini.",
    "AUS_political_events.114.a": "Sampaikan terima kasih tulus kita.",
    "AUS_political_events.115.t": "Usulan Latihan Militer Gabungan [FROM.GetAdjective]-[ROOT.GetAdjective]",
    "AUS_political_events.115.desc": "Para perwira Angkatan Darat [FROM.GetAdjective] menghubungi kita dengan harapan menggelar latihan militer gabungan bagi pasukan kita. Mereka meyakinkan kita bahwa latihan ini akan sangat menguntungkan bagi kedua negara dan kita dapat memetik banyak ilmu dari mereka, sebagaimana mereka dari kita.",
    "AUS_political_events.115.a": "Kenapa tidak?",
    "AUS_political_events.115.b": "Ini terdengar mencurigakan...",
    "AUS_political_events.116.t": "Latihan Militer Gabungan [ROOT.GetAdjective]-[FROM.GetAdjective] Berakhir",
    "AUS_political_events.116.desc": "Hari ini menandai penutupan latihan militer gabungan [ROOT.GetAdjective]-[FROM.GetAdjective]. Pasukan kita memetik manfaat besar dari latihan ini, dan kita berharap pihak [FROM.GetAdjective] merasakan hal yang sama. Mengamati lebih dekat operasional Angkatan Darat [FROM.GetAdjective] juga memberi kita gambaran utuh tentang apa yang harus kita hadapi saat rencana masa depan kita terlaksana.",
    "AUS_political_events.116.a": "Luar biasa!",
    "AUS_political_events.117.t": "Penolakan [FROM.GetAdjective] atas Latihan Militer Gabungan [ROOT.GetAdjective]-[FROM.GetAdjective]",
    "AUS_political_events.117.desc": "\\nTerlepas dari manfaat nyata bagi kita berdua, [FROM.GetNameDef] menolak usulan kita untuk latihan militer bersama. Padahal angkatan bersenjata kita dapat saling belajar satu sama lain. Ini juga semestinya menjadi peluang emas bagi kita memengaruhi [FROM.GetNameDef] menuju arah yang kita rencanakan untuk masa depan mereka.",
    "AUS_political_events.117.a": "Tidak masalah...",
    "AUS_political_events.118.t": "Organisasi Kekaisaran",
    "AUS_political_events.118.desc": "Seiring kita melangkah di jalan restorasi kekaisaran kita, masalah tata kelola kekaisaran kembali mengemuka di hadapan kita. Para pendahulu kita gagal dalam persoalan ini, menghasilkan kekaisaran luas yang terpecah-belah dan kacau. Kita disodori saran pembentukan faksi demi memastikan negeri-negeri vasal tetap setia kepada kita, sekaligus mencegah mereka saling bertikai satu sama lain.",
    "AUS_political_events.118.a": "Mereka wajib bergabung bersama kita",
    "AUS_political_events.118.b": "Biarkan kesepakatan saat ini menyelesaikan hal ini",
    "AUS_political_events.118.c": "Kita akan membentuk tata kelola organisasi yang paling tepat untuk ini!",
    "AUS_political_events.118.c.tt": "§Y[FROM.FROM.GetNameDefCap]§! akan dipaksa untuk bergabung ke dalam faksi §Y[ROOT.GetAdjective]§!",

    # 121 - 139: Balkan concessions & Georg von Trapp
    "AUS_political_events.119.t": "[FROM.GetNameDefCap] Menuntut Konsesi Tambahan",
    "AUS_political_events.119.desc": "Meskipun mereka telah mengajukan klaim wilayah yang cukup besar di Balkan, pihak [FROM.GetAdjective] tampaknya masih belum puas. Tuntutan yang mereka ajukan kali ini akan merambah lingkup pengaruh kita seandainya kita menyetujuinya, namun pada saat yang sama, konsekuensi yang mereka ancamkan jika kita menolak bisa jadi sangat mematikan.",
    "AUS_political_events.119.a": "Kita terpaksa mengalah",
    "AUS_political_events.119.b": "Kita tidak boleh membiarkan kelancangan ini!",
    "AUS_political_events.120.t": "[FROM.GetNameDefCap] Tunduk pada Tuntutan Kita",
    "AUS_political_events.120.desc": "Tuntutan wilayah yang kita layangkan kepada kepemimpinan [FROM.GetAdjective] telah diterima. Kendati kita memang sudah memperkirakan hasil ini, tetap sangat melegakan bahwa kita tidak perlu menempuh jalan kekerasan demi mengamankan kembali wilayah sah kita.",
    "AUS_political_events.120.a": "Kejayaan sejati.",
    "AUS_political_events.121.t": "[FROM.GetNameDefCap] Menolak Tuntutan Kita",
    "AUS_political_events.121.desc": "Terlepas dari klaim sah kita atas wilayah yang kini dikuasai oleh [FROM.GetAdjective], [FROM.GetLeader] memutuskan untuk tidak menyerahkan wilayah yang diminta. Ini jelas merupakan hambatan, namun kita pasti merebut kembali tanah air leluhur itu, apapun risikonya.",
    "AUS_political_events.121.a": "Kita akan merebut tanah itu kembali!",
    "AUS_political_events.122.t": "Dengung Kapal Selam [ROOT.GetAdjective]?",
    "AUS_political_events.122.desc": "Georg von Trapp dulunya adalah seorang Komandan Kapal Selam yang sangat disegani dalam jajaran Angkatan Laut Austria-Hongaria yang perkasa. Menyusul runtuhnya kekaisaran agung kita dan hilangnya seluruh garis pantai kita, ia bersama banyak veteran lainnya beralih ke profesi lain. Setelah sempat terjun ke dunia perbankan yang menguras sebagian besar kekayaannya, ia mengalihkan perhatiannya ke dunia musik.\\n\\nKini seiring kita berhasil merebut kembali kendali atas garis pantai maritim kita, von Trapp menawarkan jasanya untuk kembali mengarungi samudra luas atas nama bangsa agung kita.",
    "AUS_political_events.122.a": "Luar biasa, masukkan kembali ia ke jajaran armada laut!",
    "AUS_political_events.122.b": "Betapapun kita mengaguminya... sayangnya tidak",

    # 140 - 162: Reforming Central Powers
    "AUS_political_events.123.t": "Kaum [FROM.GetAdjective] Membentuk Kembali Blok Sentral",
    "AUS_political_events.123.desc": "Kabar bahwa Austria telah membentuk kembali Blok Sentral sampai ke telinga kita pagi ini. Persekutuan militer bersejarah ini berdiri kokoh melewati Perang Besar, namun hancur lebur seiring tumbangnya sebagian besar monarki anggotanya. Pihak [FROM.GetAdjective] kini memutuskan untuk mengobarkan kembali faksi legendaris ini, dan mengingat kita adalah bagian dari persekutuan masa lalu tersebut, mereka memandang layak untuk melayangkan undangan resmi kepada kita.",
    "AUS_political_events.123.a": "Kita akan berdiri bersatu kembali!",
    "AUS_political_events.123.b": "Sekali sudah lebih dari cukup",
    "AUS_political_events.124.t": "[FROM.GetNameDefCap] Bergabung dengan [ROOT.GetFactionName]",
    "AUS_political_events.124.desc": "Persis seperti yang kita harapkan dari sekutu setia kita, mereka menyambut hangat undangan kita untuk membangkitkan kembali faksi agung kita. Mereka sepakat untuk bergabung dalam perjuangan kita melawan tatanan dunia yang memperlakukan kita dengan begitu tidak adil di akhir Perang Besar.",
    "AUS_political_events.124.a": "Kekaisaran kita akan bangkit kembali!",
    "AUS_news_events.5.t": "Ketegangan Meruncing di Eropa Tengah",
    "AUS_news_events.5.desc": "Pergolakan politik di Austria dan sekitarnya memicu kecemasan mendalam di kalangan diplomat Eropa.",
    "AUS_news_events.5.a": "Mencemaskan",
    "AUS_news_events.5.b": "Akhirnya!",
    "AUS_news_events.6.t": "[AUS.GetNameDefCap] Membentuk Kembali Blok Sentral",
    "AUS_news_events.6.desc": "\\n\\nTanpa opsi persekutuan yang layak di kawasan terdekat mereka, [AUS.GetNameDef] memutuskan untuk membangkitkan kembali aliansi legendaris Blok Sentral. Setelah membebaskan diri dari belenggu perjanjian yang melumpuhkan mereka, negara tersebut kini menempuh jalur remiliterisasi dengan kecepatan kilat. Apakah aliansi baru ini akan menandingi kejayaan dan kedahsyatan pendahulunya di Perang Besar, masih harus dibuktikan oleh sejarah.",
    "AUS_news_events.6.a": "Sangat mencemaskan",
    "AUS_news_events.6.b": "Hari yang bersejarah!",

    # 163 - 190: Otto von Habsburg return, Habsburg city, Coup, Danubian Bloc, Elections
    "AUS_news_events.7.t": "Otto von Habsburg Kembali ke [AUS.GetNameDef]",
    "AUS_news_events.7.desc": "\\nSetelah menghabiskan sebagian besar masa hidupnya dalam pengasingan, mula-mula di [SWI.GetNameDef] dan kemudian di Pulau Madeira di [POR.GetNameDef], Otto von Habsburg akhirnya kembali ke [AUS.GetNameDef]. Sang pangeran melarikan diri dari tanah airnya pada tahun 1918 bersama orang tuanya, Kaisar Karl I dan Permaisuri Zita, pasca runtuhnya monarki di penghujung Perang Besar. Kepulangannya sebagai kepala negara [AUS.GetAdjective] menandai pembalikan arah angin politik yang sangat drastis di [AUS.GetNameDef].",
    "AUS_news_events.7.a": "Hidup sang pangeran Habsburg!",
    "AUS_news_events.7.b": "Bukan ini yang tertulis dalam naskah perjanjian damai!",
    "AUS_news_events.7.c": "Bagus untuknya",
    "AUS_news_events.8.t": "Wangsa Habsburg Kembali Menguasai Kastel Habsburg",
    "AUS_news_events.8.desc": "Di bawah kepemimpinan [AUS.GetLeader], [AUS.GetNameDef] telah merebut kembali kota dan puri leluhur Habsburg. Setelah menundukkan pihak [SWI.GetAdjective] ke bawah kehendak mereka, tujuan dari langkah ini adalah memperkuat legitimasi trah Habsburg dan menandai kembalinya [AUS.GetName] yang jauh lebih imperialis.",
    "AUS_news_events.8.a": "Mengapa mereka melakukan hal itu?",
    "AUS_news_events.8.b": "Habsburg adalah milik sah kita!",
    "AUS_news_events.9.t": "Kudeta Komunis di [FROM.GetNameDef]",
    "AUS_news_events.9.desc": "Menyusul merebaknya simpati rakyat terhadap [FROM.GetCommunistParty] di [FROM.GetNameDef] dalam kurun waktu yang panjang, sebuah peralihan kekuasaan secara damai terjadi di [FROM.GetNameDef]. Kaum Komunis mengambil alih kendali pemerintahan dengan sedikit perlawanan. \\n\\nPeristiwa ini menandai perubahan haluan radikal dari corak politik [FROM.GetNameDef] selama beberapa dekade terakhir.",
    "AUS_news_events.9.a": "Sungguh tak terduga",
    "AUS_news_events.9.b": "Kami mendoakan keberhasilan mereka!",
    "AUS_news_events.9.c": "Akhirnya!",
    "AUS_news_events.10.t": "Perang Saudara Meletus di [FROM.GetNameDef]",
    "AUS_news_events.10.desc": "Perang Saudara berdarah meletus di [FROM.GetNameDef]. Partai Komunis [FROM.GetCommunistParty] melancarkan pemberontakan bersenjata melawan penguasa dari faksi [FROM.GetNeutralParty]. Menggalang gelombang dukungan rakyat dalam jumlah besar baru-baru ini, kaum komunis telah bertransformasi menjadi kekuatan militer yang patut diperhitungkan di [FROM.GetNameDef].",
    "AUS_news_events.10.a": "Sungguh gila",
    "AUS_news_events.10.b": "Kerja bagus dan semoga sukses!",
    "AUS_news_events.10.c": "Maju terus kawan!",
    "AUS_news_events.11.t": "[AUS.GetNameDefCap] Membentuk Blok Donau",
    "AUS_news_events.11.desc": "Memutar haluan secara radikal dari masa lalunya, kepemimpinan [AUS.GetAdjective] di bawah [AUS.GetLeader] telah memutuskan mendirikan faksi persekutuan mereka sendiri. Ia menyuarakan harapan agar seluruh kaum buruh di Eropa Tengah bangkit melawan para penindas mereka dan bergabung dalam perjuangan suci ini demi membela hak-hak rakyat jelata.",
    "AUS_news_events.11.a": "Mengapa mereka berbuat sejauh itu?",
    "AUS_news_events.11.b": "Kami mendoakan yang terbaik bagi mereka!",
    "AUS_news_events.11.c": "Hari yang agung bagi [AUS.GetNameDef]!",
    "AUS_news_events.12.t": "[AUS.GetNameDefCap] Kembali Menggelar Pemilu Demokratis",
    "AUS_news_events.12.desc": "\\nUntuk pertama kalinya sejak 11 September 1930, [AUS.GetNameDef] berhasil menyelenggarakan pemilihan umum demokratis. Antusiasme rakyat luar biasa tinggi dan saat penghitungan suara tuntas, [AUS.GetLeader] dari [AUS.GetDemocraticParty] tampil sebagai pemenang. Ia kini mengemban amanah berat memandu negerinya melangkah di jalan baru yang lebih demokratis dan bermartabat.",
    "AUS_news_events.12.a": "Luar biasa",
    "AUS_news_events.12.b": "Tercatat",

    # 191 - 199: Early Hungary events (WW_hungary.1 to 3)
    "WW_hungary.1.t": "[HUN.GetName] Meluncurkan Program Manufaktur Sekutu",
    "WW_hungary.1.desc": "Sekutu kita [HUN.GetNameDef] telah memprakarsai sebuah program untuk bersama-sama mengembangkan pesawat terbang di dalam faksi kita, dan memulai langkah ini dengan berinvestasi pada riset manufaktur kita demi memajukan teknologi penerbangan bersama di masa depan.",
    "WW_hungary.1.a": "Sebuah berkah yang tak ternilai",
    "WW_hungary.2.t": "Pengiriman Senjata dari [FROM.GetAdjective] Tiba",
    "WW_hungary.2.desc": "Pemerintah [FROM.GetAdjective] secara terang-terangan mengambil sikap membela negara kita dalam upaya perang kita. Sebagai wujud nyata dukungan baru mereka, mereka telah mengirimkan kargo persenjataan besar kepada kita. Pasokan ini niscaya akan memperkuat posisi kita dalam perang ini.",
    "WW_hungary.2.a": "Bagus sekali!",
    "WW_hungary.3.t": "Wafatnya Perdana Menteri Gyula Gömbös",
    "WW_hungary.3.desc": "Perdana menteri kita, seorang perwira militer dan pendiri Asosiasi Pertahanan Nasional Hongaria (MOVE), Gyula Gömbös, dilaporkan telah menghembuskan napas terakhir akibat kanker testis saat menjalankan misi diplomatik di München. Kendati [ROOT.GetLeader] telah menyiapkan calon pengganti, yaitu tokoh sentris Kálmán Darányi, pertanyaan besar tetap membayangi mengenai nasib organisasi paramiliter fasis yang dulunya dipimpin langsung oleh mendiang Gömbös. Mengingat kesamaan sikap anti-komunis antara mereka dan [ROOT.GetLeader], sangat mungkin untuk merangkul mereka bekerja demi kita, namun ketidakpastian mengenai loyalitas sejati mereka dapat menjadi duri dalam daging jika kita memasukkan mereka ke dalam tubuh angkatan bersenjata. Bagaimana kita harus bersikap terhadap MOVE?",
    "WW_hungary.3.a": "Kita harus berupaya mengintegrasikan MOVE"
}

# Verify and save
with open('scripts/chunks/chunk_2.json', 'r', encoding='utf-8') as f:
    chunk_items = json.load(f)

missing = []
for it in chunk_items:
    k = it['key']
    if k not in trans:
        missing.append(k)

if missing:
    print(f"Warning: {len(missing)} missing keys in chunk 2: {missing[:10]}")
else:
    print(f"Success! All {len(chunk_items)} keys in chunk 2 are translated!")

with open('scripts/chunks/trans_chunk_2.json', 'w', encoding='utf-8') as f:
    json.dump(trans, f, indent=2, ensure_ascii=False)
print("Saved scripts/chunks/trans_chunk_2.json")
